import AppKit
import UniformTypeIdentifiers

/// The Media tab (spec §4.3): every imported file with its thumbnail, name,
/// duration, dimensions, rate and badges; Add Media… (⇧⌘I); Finder drops onto
/// the panel; a drag from a row to a timeline track or onto the canvas; the
/// find band road map 2's phase 8c added — a search, a sort and an "unused
/// only" switch (`MediaListFilter.swift`) — and the row menu: Insert at
/// Playhead, Overwrite at Playhead, Reveal in Timeline, Reveal in Finder,
/// Relink…, Remove.
///
/// There is no left panel in this app (§11), so this list IS the library.
/// Files are referenced, never copied (path + bookmark, §11), which is why a
/// row can be "missing" and why Relink… lives here.
///
/// **The find band does not rebuild the pane, and that is the whole design of
/// it.** `InspectorPaneView.rebuild()` removes every arranged subview and
/// asks `makeSections()` for a new set, `InspectorViewController.refresh` runs
/// it whenever `structureSignature` changes, and nothing in the inspector
/// preserves the first responder across one — so a search field built inside
/// `makeSections()` with the filtered set in the signature would be destroyed
/// by the first keystroke that changed the list, taking the field editor and
/// the caret with it (measured: removing a text field's ancestor leaves
/// `currentEditor()` nil and the window itself as first responder). So the
/// signature stays what it always was — a statement about the MODEL's shape —
/// and `arrange()` applies the search, the sort and the switch to the rows
/// that are already built, by hiding and re-ordering the list stack's
/// arranged subviews. Both are measured, not assumed: an `isHidden` arranged
/// subview leaves an `NSStackView`'s layout entirely (four 20 pt rows measure
/// 89 pt, three of them 66), and `insertArrangedSubview(_:at:)` MOVES a view
/// that is already arranged rather than duplicating it (the subview count
/// does not change) while leaving the window's first responder and the
/// caret's offset exactly where they were.
final class MediaPane: InspectorPaneView {
    override var tab: InspectorTab { .media }

    /// The Media tab always has something to show — including when there is
    /// nothing imported yet, which is when Add Media… matters most.
    override var emptyMessage: String? { nil }

    /// The rows, in the order the model lists them, each with the id it
    /// draws. The id is kept beside the view rather than read back off it so
    /// that `arrange()` can look the CURRENT entry up in the snapshot: a
    /// relink changes a file's name without changing this pane's signature,
    /// and a cached `MediaSnapshot` would sort and search against the name
    /// the row no longer shows.
    ///
    /// Internal rather than private for one caller: `select(_:)` redraws them
    /// and lives in `MediaPaneCommands.swift`, which is where the row's seven
    /// commands went when this file crossed the size cap. That is the whole
    /// cost of the split.
    var rows: [(media: UInt32, view: MediaRowView)] = []

    /// The find band's state. View state, not persisted, and not part of the
    /// signature below — `MediaListFilter` argues both.
    private var filter = MediaListFilter()

    /// The three things `arrange()` changes without a rebuild. Weak, because
    /// the view hierarchy owns them and a rebuild replaces all three;
    /// `InspectorPaneView.rebuild()` holds the previous generation one build
    /// longer, so a stale strong reference here would outlive the pane's own
    /// rule about that.
    private weak var listStack: NSStackView?
    private weak var tallyLabel: InspectorRowLabel?
    private weak var noMatchesRow: NSView?

    /// The order `arrange()` last put the rows in, so it can leave the stack
    /// alone when nothing has moved — it runs on every refresh, and a live
    /// canvas drag refreshes this panel thirty times a second.
    private var arrangedOrder: [UInt32] = []

    /// The MODEL's shape: which media exist and whether each one's file is
    /// there. Deliberately says nothing about the search text, the sort or
    /// the unused-only switch — see the class doc: putting the filtered set
    /// in here is precisely the bug this pane is built to avoid.
    override var structureSignature: String {
        // `:c` for a media with a cursor file: a Locate… or a Remove adds or
        // drops it, so the Cursor section's rows are rebuilt (CU-54).
        let media = binding.snapshot.media.map { entry -> String in
            "\(entry.id):\(mediaURL(for: entry) == nil ? "missing" : "ok")"
                + (entry.cursor == nil ? "" : ":c")
        }
        return "media|" + media.joined(separator: ",")
    }

    override init(inspector: InspectorViewController) {
        super.init(inspector: inspector)
        // Finder drops land on the panel (§4.3). The editor's root view takes
        // file drops too, but it OPENS them as documents; a drop on this
        // panel means "add to this project", so the pane claims the type
        // first by being the deeper registered view.
        registerForDraggedTypes([.fileURL])
        NotificationCenter.default.addObserver(
            self, selector: #selector(cacheChanged(_:)), name: .mediaCacheDidChange, object: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("MediaPane does not support NSCoder")
    }

    deinit {
        NotificationCenter.default.removeObserver(self)
    }

    // MARK: - Sections

    /// The redesign makes this tab a real LIST rather than a stack of button
    /// rows (handoff README, Part 2 §5): a 38 pt action row, the rows 3 pt
    /// apart, and a 40 pt footer carrying Consolidate… and one line saying
    /// what it does. It is still ONE `InspectorSection`, because the panel's
    /// shell builds every pane from sections and this one has no business
    /// forking that.
    override func makeSections() -> [InspectorSection] {
        rows = []
        listStack = nil
        noMatchesRow = nil
        arrangedOrder = []
        var content: [NSView] = [actionRow()]
        if binding.snapshot.media.isEmpty {
            // No find band with nothing to find: the band would be three dead
            // controls over a line saying the list is empty, and the pane is
            // rebuilt the moment the first file lands.
            content.append(
                inspectorRow(nil, [InspectorRowLabel("Drop files here, or use Add Media….")]))
        } else {
            content.append(findRow())
            content.append(listView())
            content.append(noMatchesView())
        }
        content.append(footerRow())
        // The rows exist and the band's controls hold the state, so the
        // filter can be applied to this build before it is ever shown — which
        // is what carries a search across the rebuild an import causes.
        arrange()
        let files = InspectorSection(id: "media.files", title: "Media", rows: content)
        // Camera Log (spec §11 GR-16) acts on a video file, so it is there
        // once the project has one (`MediaPane+CameraLog.swift`); HDR10 (spec
        // §11 HD-12) on a PQ file, once the project has one
        // (`MediaPane+HDR10.swift`); Cursor (spec §11 CU-54) on a video with a
        // picture, once the project has one (`MediaPane+Cursor.swift`).
        let media = binding.documentSnapshot.media
        let video = media.contains { $0.kind == .video }
        let pq = media.contains { $0.color?.pq != nil }
        let cursor = MediaPane.showsCursorSection(media)
        return (video ? [files, cameraLogSection()] : [files]) + (pq ? [hdr10Section()] : [])
            + (cursor ? [cursorSection()] : [])
    }

    /// Add Media…, its ⇧⌘I hint, and the item count at the trailing edge.
    ///
    /// The count used to be a plain label built once per rebuild, because it
    /// changed only when the media list did. It changes with the FILTER now —
    /// "3 of 40 items" is the one line that stops a narrowed list reading as a
    /// lost library — so the label is held and `arrange()` writes it. It is
    /// still not an `OptionControl`: those read the model, and this reads the
    /// pane's own view state.
    private func actionRow() -> NSView {
        let add = commandButton(
            "Add Media…", #selector(EditorViewController.addMediaFiles(_:)),
            toolTip: "Import files into this project (⇧⌘I)")

        let count = binding.snapshot.media.count
        let label = MediaPane.caption(MediaPane.tally(shown: count, of: count))
        tallyLabel = label
        return MediaPane.bar(
            height: 38, border: .bottom,
            views: [add, MediaPane.caption("⇧⌘I"), MediaPane.spacer(), label])
    }

    /// The item count, and the one place it is spelled.
    ///
    /// **One rule, not two**, and the shape is the fix. This used to return
    /// early with `"\(shown) of \(total) items"` whenever the list was
    /// narrowed and only then fall through to a `switch` that spelled "No
    /// media" / "1 item" / "N items" — so the plural logic lived in the ONE
    /// branch that could never reach `total == 1`, and a one-file library
    /// with the search on read "0 of 1 items". Splitting a spelling across
    /// two branches is what invites that back, so the noun is built once and
    /// the narrowed line is that same noun with a prefix.
    ///
    /// The plural agrees with `total`, because `total` is the count the noun
    /// qualifies: "0 of 1 item" is one item, none of it shown. (English is
    /// not universal about that — "0 items" is plural where "1 item" is not,
    /// which is exactly why the number the noun belongs to has to be named
    /// rather than assumed.)
    private static func tally(shown: Int, of total: Int) -> String {
        if total == 0 { return "No media" }
        let items = total == 1 ? "1 item" : "\(total) items"
        return shown == total ? items : "\(shown) of \(items)"
    }

    /// The find band: the search field on its own line, the sort popup and
    /// the unused-only switch under it.
    ///
    /// **Two lines because three controls do not fit on one**, measured
    /// rather than felt: the popup is 116 pt (the `InspectorMetrics` width
    /// that holds "Import Order" in `DS.mono(11)` with its chevron), the
    /// checkbox is 77 (13 pt box, 6 pt gap, 58 pt of `DS.sans(11)`), and the
    /// field wants about 110 to show its own placeholder — 319 pt against the
    /// 284 the default 304 pt panel leaves inside the section inset, and 260
    /// at the 280 pt minimum width. One line "fits" only at a width nobody is
    /// guaranteed to have, and the failure mode is the search box shrinking
    /// to nothing while the two controls beside it stay whole.
    private func findRow() -> NSView {
        let controls = MediaListFilter.controls(
            current: { [weak self] in self?.filter ?? MediaListFilter() },
            apply: { [weak self] next in self?.apply(next) })
        return MediaPane.bar(
            height: 60, border: .bottom,
            lines: [
                [controls.search],
                [MediaPane.caption("Sort"), controls.sort, MediaPane.spacer(),
                 controls.unusedOnly],
            ])
    }

    /// A control wrote a new filter: keep it and re-arrange, unless it says
    /// exactly what the old one said (every keystroke in the search field
    /// arrives here, and most of them are `guard`ed out by this line).
    ///
    /// The controls are refreshed on the way out because
    /// `OptionCheckboxControl` and `OptionPopupControl` redraw from
    /// `refresh()` alone: they write through their closure and trust the panel
    /// to come back round, which it does for a document edit and does not for
    /// view state. It belongs here rather than in `arrange()` — this is the
    /// path a control WROTE on, and on the other two paths the panel has
    /// refreshed them already.
    private func apply(_ next: MediaListFilter) {
        guard next != filter else { return }
        filter = next
        arrange()
        refreshOptionControls(in: self)
    }

    /// The rows themselves, in their own stack so they sit 3 pt apart — the
    /// section's own row spacing is 6 and is shared with every other pane.
    ///
    /// Built in the MODEL's order every time; `arrange()` is what puts them in
    /// the sort's order, and it runs before this build is ever on screen.
    private func listView() -> NSView {
        let stack = NSStackView()
        stack.orientation = .vertical
        stack.alignment = .leading
        stack.spacing = 3
        for media in binding.snapshot.media {
            let row = MediaRowView(media: media.id, pane: self)
            rows.append((media: media.id, view: row))
            stack.addArrangedSubview(row)
            row.widthAnchor.constraint(equalTo: stack.widthAnchor).isActive = true
        }
        listStack = stack
        return stack
    }

    /// The line under a list every row of which the filter has hidden. Built
    /// with the list and shown by `arrange()`, because a filter change must
    /// not rebuild anything — and a list that has silently gone blank is the
    /// worst thing a search can do to a library.
    ///
    /// The sentence measures 191 pt in `DS.sans(11)` against the 264 pt a row
    /// has in the default panel and 240 at the 280 pt minimum, so it is whole
    /// at every width — the footer's own line records what happens when that
    /// is not checked.
    private func noMatchesView() -> NSView {
        let row = inspectorRow(
            nil, [InspectorRowLabel("No media matches the search or the filter.")])
        row.isHidden = true
        noMatchesRow = row
        return row
    }

    /// The search, the sort and the unused-only switch applied to the rows
    /// this pane already holds — no rebuild, so the field being typed into
    /// keeps its caret (the class doc says why that is the point).
    ///
    /// The order is applied to EVERY row and the hiding to every row
    /// separately: moving a row and hiding one are different jobs, and a
    /// hidden row that keeps its place in the sort comes back where it
    /// belongs when the search is cleared. Nothing is written that does not
    /// have to be — this runs on every refresh, including a live gesture's
    /// thirty a second.
    private func arrange() {
        // The DOCUMENT's snapshot, and only one of the three things read off
        // it needs to be (road map 2's phase 9): `filter.admits` asks
        // `usesMedia`, and inside a nest a scoped view holds the NEST's clips
        // at top level and the timeline's nowhere — so a file used only by a
        // timeline clip would read as unused and "Unused only" would offer to
        // remove it. `media` itself is the same list either way (the view
        // carries the parent's `media[]` unchanged), so the order and the
        // tally are unaffected; this is written as one local so the question
        // cannot be asked two ways in one method.
        let snapshot = binding.documentSnapshot
        let order = filter.ordered(snapshot.media)
        if let stack = listStack, order != arrangedOrder {
            var index = 0
            for id in order {
                guard let row = rows.first(where: { $0.media == id })?.view else { continue }
                stack.insertArrangedSubview(row, at: index)
                index += 1
            }
            arrangedOrder = order
        }
        var shown = 0
        for row in rows {
            let visible = snapshot.media(row.media).map { filter.admits($0, in: snapshot) } ?? false
            if row.view.isHidden == visible { row.view.isHidden = !visible }
            row.view.syncToolTip()
            if visible { shown += 1 }
        }
        let empty = shown == 0 && !rows.isEmpty
        if noMatchesRow?.isHidden == empty { noMatchesRow?.isHidden = !empty }
        let tally = MediaPane.tally(shown: shown, of: snapshot.media.count)
        if tallyLabel?.stringValue != tally { tallyLabel?.stringValue = tally }
        dropHiddenSelection()
        refreshOptionControls(in: self)
    }

    /// The panel's own per-change refresh, plus a re-arrangement.
    ///
    /// The second half is not tidiness: "unused only" is a question about the
    /// CLIPS, and deleting the last clip that used a file changes no part of
    /// `structureSignature` — the media list is the same list — so without
    /// this the row that has just become unused would not appear until
    /// something else rebuilt the pane. A relink from one present file to
    /// another is the same shape: the name the sort reads changes and the
    /// signature does not. Everything above writes only what it has to, so
    /// the ordinary case — nothing moved, nothing hidden, the same count —
    /// costs one sort and a walk of a few dozen rows.
    override func refresh() {
        super.refresh()
        arrange()
    }

    /// Consolidate belongs beside the list it acts on: this pane is where the
    /// "files are referenced, never copied" rule is visible (a row can be
    /// missing, and Relink… lives here), so it is where the one command that
    /// ends the rule should be reachable. The menu item is the same action;
    /// both validate through the editor.
    ///
    /// The design puts it in a footer with a line saying what it does, so the
    /// one command in the app that copies gigabytes is never a mystery
    /// button. The line is the SHORT one; the sentence is the tooltip on both
    /// halves of the row.
    private func footerRow() -> NSView {
        let binding = self.binding
        let consolidate = commandButton(
            "Consolidate…", #selector(EditorViewController.consolidateMedia(_:)),
            toolTip: MediaPane.consolidateNote,
            enabled: { !binding.snapshot.media.isEmpty })

        let note = MediaPane.caption(MediaPane.consolidateLine, font: DS.sans(11))
        note.toolTip = MediaPane.consolidateNote
        note.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        return MediaPane.bar(height: 40, border: .top, views: [consolidate, note])
    }

    /// The line the footer SHOWS — the mock's own wording.
    ///
    /// **Pitfall:** the sentence below measures 251.2 pt in `DS.sans(11)`,
    /// against the 192 pt left beside the 84 pt Consolidate… button in the
    /// 304 pt panel and 168 pt at the 280 pt minimum (all measured) — so it
    /// truncated at the default width and at every width below it, and only
    /// came out whole past about 363 pt, which nobody but a user who has
    /// dragged the panel nearly to its 440 pt maximum ever sees. A
    /// half-sentence is a poor description of the one command that copies
    /// gigabytes. This line is 146.7 pt and fits the whole range.
    private static let consolidateLine = "Copies sources into the package"

    /// The whole sentence, kept as the tooltip on the button and on the line
    /// so the short version is never the only thing said.
    private static let consolidateNote = "Copies every referenced file into this project's package."

    /// A machine-face caption — the ⇧⌘I hint, the item count, the footer's
    /// one-liner. `InspectorRowLabel` is the shared label; only its face
    /// changes, so the pane does not grow a label class of its own.
    private static func caption(_ text: String, font: NSFont = DS.mono(10)) -> InspectorRowLabel {
        let label = InspectorRowLabel(text)
        label.font = font
        label.textColor = DS.textFaint
        return label
    }

    /// The stretchy gap that pushes a bar's trailing cluster out — the same
    /// low-hugging filler `inspectorRow` uses.
    private static func spacer() -> NSView {
        let view = NSView()
        view.setContentHuggingPriority(NSLayoutConstraint.Priority(1), for: .horizontal)
        view.setContentCompressionResistancePriority(
            NSLayoutConstraint.Priority(1), for: .horizontal)
        return view
    }

    /// One of the pane's two chrome bands, drawn EDGE TO EDGE.
    ///
    /// **Pitfall:** a `BarView` fills `DS.chromeBackground`, which is exactly
    /// what `InspectorViewController` paints the panel with — so the band
    /// itself is invisible and its 1 pt hairline is the whole of it. And a
    /// section's rows are inset by `InspectorMetrics.inset`, so that hairline
    /// stopped 10 pt short at each end and read as a floating stub rather than
    /// a rule; the 38 pt action row and the 40 pt footer were structurally
    /// there and visually absent.
    ///
    /// The fix keeps `BarView` and overhangs the inset instead: the bar is a
    /// subview of the section row pinned 10 pt PAST each side, and the content
    /// stack takes those 10 pt back as padding, so the rule spans the panel
    /// while the controls stay on the panel's gutter — the mock's own
    /// arrangement (a band with `padding: 0 10px`). The alternative was to
    /// inset the section's rows less, and the section shell is shared with
    /// every other pane, so it is not this one's to change.
    ///
    /// The overhang is legal because nothing between the row and the pane
    /// clips to its bounds — measured by rendering the same hierarchy
    /// offscreen (layer-backed root → scroll view → pane stack → section
    /// stack → row), where the bar paints the full panel width.
    private static func bar(height: CGFloat, border: BarView.Border, views: [NSView]) -> NSView {
        bar(height: height, border: border, lines: [views])
    }

    /// The same band with more than one LINE of controls in it — phase 8c's
    /// find band, which needs two.
    ///
    /// One band rather than two stacked ones: two would each carry a hairline
    /// and each take one of the section's 7 pt row gaps, which is 15 pt of
    /// chrome and a second rule for no extra meaning. A single line is still
    /// built exactly as it was — the horizontal stack IS the content, with no
    /// wrapper around it — so the two existing bands are laid out to the pixel
    /// they always were.
    private static func bar(
        height: CGFloat, border: BarView.Border, lines: [[NSView]]
    ) -> NSView {
        let row = NSView()
        let bar = BarView(border: border)
        bar.translatesAutoresizingMaskIntoConstraints = false
        row.addSubview(bar)
        let rows = lines.map { views -> NSStackView in
            let line = NSStackView(views: views)
            line.orientation = .horizontal
            line.alignment = .centerY
            line.spacing = 8
            return line
        }
        let stack: NSView
        if rows.count == 1 {
            stack = rows[0]
        } else {
            let column = NSStackView(views: rows)
            column.orientation = .vertical
            column.alignment = .leading
            column.spacing = 6
            // Each line spans the band, so a spacer on any of them pushes to
            // the same trailing edge and a flexible field on another fills the
            // same width.
            for line in rows {
                line.widthAnchor.constraint(equalTo: column.widthAnchor).isActive = true
            }
            stack = column
        }
        stack.translatesAutoresizingMaskIntoConstraints = false
        bar.addSubview(stack)
        let inset = InspectorMetrics.inset
        NSLayoutConstraint.activate([
            row.heightAnchor.constraint(equalToConstant: height),
            bar.topAnchor.constraint(equalTo: row.topAnchor),
            bar.bottomAnchor.constraint(equalTo: row.bottomAnchor),
            bar.leadingAnchor.constraint(equalTo: row.leadingAnchor, constant: -inset),
            bar.trailingAnchor.constraint(equalTo: row.trailingAnchor, constant: inset),
            stack.leadingAnchor.constraint(equalTo: bar.leadingAnchor, constant: inset),
            stack.trailingAnchor.constraint(equalTo: bar.trailingAnchor, constant: -inset),
            stack.centerYAnchor.constraint(equalTo: bar.centerYAnchor),
        ])
        return row
    }

    /// Thumbnails and waveforms land after the import returns
    /// (`MediaImporter` posts repeatedly as they arrive), so this only marks
    /// the rows dirty — never a rebuild.
    @objc private func cacheChanged(_ note: Notification) {
        for row in rows { row.view.invalidateThumbnail() }
    }

    // MARK: - Finder drops

    private func droppedURLs(_ sender: any NSDraggingInfo) -> [URL] {
        let options: [NSPasteboard.ReadingOptionKey: Any] = [.urlReadingFileURLsOnly: true]
        let urls = sender.draggingPasteboard.readObjects(forClasses: [NSURL.self], options: options)
        return (urls as? [URL]) ?? []
    }

    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation {
        droppedURLs(sender).isEmpty ? [] : .copy
    }

    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation {
        droppedURLs(sender).isEmpty ? [] : .copy
    }

    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool {
        let urls = droppedURLs(sender)
        guard !urls.isEmpty else { return false }
        inspector?.onImportFiles?(urls)
        return true
    }
}

import AppKit

/// One file in the list: thumbnail, name, the meta line, and the audio and
/// missing badges. Drawn rather than composed from controls — a row has no
/// editable field, and drawing keeps a list of dozens cheap.
///
/// The redesign's row is 52 pt with a 34 × 38 thumbnail (handoff README,
/// Part 2 §5). The old one was 56 pt around a 72-wide tile, which read as a
/// strip of filmstrip frames rather than as a list; the narrow portrait well
/// makes the NAME the thing you scan down.
///
/// **Why this is a file of its own.** `MediaPane.swift` stood at 822 lines
/// against app/CLAUDE.md's ~600 cap, and road map 2's phase 8 came to give
/// the Media tab a search field, a sort popup, an "unused only" filter and a
/// Reveal in Timeline context item — so the pane had to give something up
/// before it took any of them on. That is the payment
/// `LayerRenderersText.swift` made in phase 6 and `ExporterSettings.swift`
/// and `ExportSheetOptions.swift` made in phase 7, and it is worth noting
/// that phase 8's four additions landed on BOTH sides of this cut: the three
/// controls are the list's and the context item is a row's, so each half got
/// the room it needed. The room was not ENOUGH — phase 6's warning arriving
/// again, that a cut's estimate is worth about two thirds of the truth — so
/// phase 8c cut a second time, and the row commands the pane keeps are
/// `MediaPaneCommands.swift` now.
///
/// **The cut falls below the DRAG rather than under the row's closing
/// brace**, which is the one decision in it. A row is a drag source (§4.3),
/// and everything that followed it in the old file is there to serve that
/// drag: the private pasteboard type it writes, the two enums that name
/// where it may land, the session that carries it in flight, and the two
/// destination views that report a landing back. Cutting under the class
/// would have left the source in one file and the vocabulary it drags with
/// in another — a seam through the middle of one sentence. What the pane
/// keeps of the drag is the one part a row cannot do: `drop(_:on:target:)`
/// performs the edit, as `select`, `place`, `reveal`, `relink` and `remove`
/// do for the row menu, and every one of those goes through `binding`, which
/// is the pane's business and never a row's. The pane keeps the LIST — its
/// one section, its bands, and the Finder drop onto the panel.
///
/// **Nothing widened**, and that is measured rather than assumed. A type
/// carries its own scope, so every `private` member below keeps the privacy
/// it had — where splitting a TYPE across files costs each crossing member
/// its own, the toll `ExporterLoudness.swift` records and the two
/// `extension ExportSheetController` files pay. The row already reached the
/// pane through internal members and the pane already reached the row
/// through two (`init(media:pane:)` and `invalidateThumbnail()`), so the
/// file boundary changed no declaration at all. It is
/// `ExportProgressSheetController.swift`'s free cut a second time.
final class MediaRowView: NSView, NSDraggingSource {
    static let height: CGFloat = 52

    private static let thumbSize = NSSize(width: 34, height: 38)
    private static let padding: CGFloat = 8
    /// Thumbnail to text, per the design's row.
    private static let gap: CGFloat = 9

    private let media: UInt32
    private weak var pane: MediaPane?
    private var thumbnail: CGImage?
    private var triedThumbnail = false
    private var mouseDownAt: CGPoint?
    private var hovered = false

    /// Whether this row is the document's selected media. Read rather than
    /// stored, because the pane is rebuilt whole whenever the media list
    /// changes and per-row state would not survive it.
    private var selected: Bool { pane?.binding.document?.selectedMedia == media }

    init(media: UInt32, pane: MediaPane) {
        self.media = media
        self.pane = pane
        super.init(frame: .zero)
        wantsLayer = true
        syncToolTip()
    }

    /// The row is a drag source (§4.3) and nothing about it says so. The
    /// list has no room for a line that does, so the row says it itself.
    static let dragHint =
        "Drag to a timeline track, or onto the canvas. Hold ⌥ to insert, ⇧⌥ to overwrite."

    /// The row's tooltip: the drag hint, and above it, for a copy, where the
    /// copy lives (spec §11 #228-O, Q1 and Q2) — the Media tab has no path
    /// line to say it in.
    static func toolTip(for entry: MediaSnapshot) -> String {
        // A LUT is never dragged (spec §11 GR-8): it is applied as a look.
        if entry.kind == .lut { return "A LUT: apply it to clips as a look." }
        guard let original = entry.original else { return dragHint }
        let folder = (entry.path as NSString).deletingLastPathComponent
        let home =
            folder.hasSuffix("/\(AppSupport.folderName)/Rewrapped")
            ? "Frame Job's Rewrapped folder" : "this project's package"
        return "\(original.path) — copied into \(home).\n" + dragHint
    }

    /// Keeps the tooltip current after a relink or a consolidate; written
    /// only when it changed, so the tooltip manager is not reset each pass.
    func syncToolTip() {
        let wanted = entry.map(Self.toolTip(for:)) ?? Self.dragHint
        if toolTip != wanted { toolTip = wanted }
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("MediaRowView does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: Self.height)
    }

    private var entry: MediaSnapshot? { pane?.binding.snapshot.media(media) }

    func invalidateThumbnail() {
        triedThumbnail = false
        thumbnail = nil
        needsDisplay = true
    }

    /// The cached first-second thumbnail, or a decoded still for an image
    /// file. Loaded once per row: `MediaImporter` posts when a cache lands and
    /// `invalidateThumbnail()` asks for it again.
    private func loadThumbnailIfNeeded() {
        guard !triedThumbnail else { return }
        triedThumbnail = true
        guard let pane = pane, let entry = entry else { return }
        if let cache = pane.binding.document?.cacheDirectory,
           let image = MediaImporter.loadThumbnail(for: media, index: 0, in: cache)
        {
            thumbnail = image
            return
        }
        // An HLG or PQ still waits for its tile, never ImageIO's tone map (spec §11 HD-21).
        guard entry.kind == .image, let url = mediaURL(for: entry),
            StillColor.conversion(at: url) == nil
        else { return }
        thumbnail = MediaImporter.decodeImage(url, maxPixelSize: 256)
    }

    // MARK: Hover

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // ONLY this view's own areas. `toolTip` is implemented as a tracking
        // area owned by `NSToolTipManager`, and it is in `trackingAreas` like
        // any other: the usual `trackingAreas.forEach(removeTrackingArea)`
        // deletes it on the first layout pass — which in an autolayout stack
        // inside a scroll view is immediately — and nothing ever puts it back,
        // so the row's one statement that it is a drag source never appears.
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        // `.inVisibleRect` keeps the area right as the list scrolls under the
        // pointer; the rect argument is then ignored.
        addTrackingArea(
            NSTrackingArea(
                rect: bounds,
                options: [.mouseEnteredAndExited, .activeInKeyWindow, .inVisibleRect],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) {
        hovered = true
        needsDisplay = true
    }

    override func mouseExited(with event: NSEvent) {
        hovered = false
        needsDisplay = true
    }

    // MARK: Drawing

    override func draw(_ dirtyRect: NSRect) {
        guard let entry = entry else { return }
        loadThumbnailIfNeeded()
        let missing = mediaURL(for: entry) == nil

        // A row is an object now, not a band with a rule under it: one
        // hairline box on the list-row radius, and the hover fill inside the
        // same shape so the two never disagree by half a pixel.
        let box = NSBezierPath(
            roundedRect: bounds.insetBy(dx: 0.5, dy: 0.5),
            xRadius: DS.listRowRadius, yRadius: DS.listRowRadius)
        if selected {
            DS.accent.withAlphaComponent(0.14).setFill()
            box.fill()
        } else if hovered {
            DS.hoverFill.setFill()
            box.fill()
        }
        (selected ? DS.accent : DS.border).setStroke()
        box.stroke()

        let thumb = NSRect(
            x: Self.padding, y: ((bounds.height - Self.thumbSize.height) / 2).rounded(),
            width: Self.thumbSize.width, height: Self.thumbSize.height)
        let well = NSBezierPath(
            roundedRect: thumb, xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        NSColor.controlBackgroundColor.setFill()
        well.fill()
        if let image = thumbnail {
            // Aspect FILL, clipped to the well: the well is portrait and most
            // footage is not, so fitting would leave a 34 × 19 stamp floating
            // in a box twice its height.
            NSGraphicsContext.current?.saveGraphicsState()
            well.addClip()
            let scale = max(
                thumb.width / CGFloat(image.width), thumb.height / CGFloat(image.height))
            let size = CGSize(
                width: CGFloat(image.width) * scale, height: CGFloat(image.height) * scale)
            TimelineDraw.image(
                image,
                in: CGRect(
                    x: thumb.midX - size.width / 2, y: thumb.midY - size.height / 2,
                    width: size.width, height: size.height))
            NSGraphicsContext.current?.restoreGraphicsState()
        } else {
            TimelineDraw.symbol(
                entry.kind == .audio ? "waveform" : entry.kind == .lut ? "cube" : "photo",
                fallback: "▦", in: thumb,
                tint: DS.textFaint)
        }
        DS.border.setStroke()
        NSBezierPath(
            roundedRect: thumb.insetBy(dx: 0.5, dy: 0.5), xRadius: DS.controlRadius,
            yRadius: DS.controlRadius
        ).stroke()

        // The badges moved to the trailing edge: a 52 pt row has no third
        // line to hang them under, and "missing" is the one thing in this
        // list that must never be the part that got cropped.
        var trailing = bounds.maxX - Self.padding
        if missing {
            trailing = drawBadge("missing", endingAt: trailing, color: DS.coral)
        }
        if entry.hasAudio {
            trailing = drawBadge("audio", endingAt: trailing, color: DS.clipAudio)
        }

        let textX = thumb.maxX + Self.gap
        let width = max(trailing - textX, 10)
        // Truncating, not clipping: the meta line is longer than the space a
        // row with badges leaves ("00:00:21:00 · 1080×1920 · 25 fps" against
        // about 150 pt), and `TimelineDraw.label` would cut it mid-glyph — an
        // ellipsis at least says that something was left out.
        TimelineDraw.truncated(
            entry.name, in: CGRect(x: textX, y: 11, width: width, height: 16),
            font: DS.sans(12), color: DS.textStrong)
        TimelineDraw.truncated(
            metaLine(entry), in: CGRect(x: textX, y: 28, width: width, height: 13),
            font: DS.mono(10), color: DS.textMuted)
    }

    private func metaLine(_ entry: MediaSnapshot) -> String {
        var parts: [String] = []
        if entry.duration > 0 {
            parts.append(
                ReelTime.format(entry.duration, fps: entry.fps, frames: true))
        }
        if entry.width > 0, entry.height > 0 {
            parts.append("\(entry.width)×\(entry.height)")
        }
        if entry.hasVideo, entry.fps.double > 0 {
            parts.append("\(entry.fps.displayName) fps")
        }
        if parts.isEmpty { parts.append(entry.kind.displayName) }
        return parts.joined(separator: " · ")
    }

    /// One trailing badge, laid out right to left; returns the x the NEXT one
    /// should end at, so a row with both stacks them inward.
    @discardableResult
    private func drawBadge(_ text: String, endingAt x: CGFloat, color: NSColor) -> CGFloat {
        let attributes: [NSAttributedString.Key: Any] = [
            .font: DS.mono(9), .foregroundColor: color,
        ]
        let size = text.size(withAttributes: attributes)
        let width = size.width + 10
        let rect = NSRect(x: x - width, y: bounds.midY - 6.5, width: width, height: 13)
        let path = NSBezierPath(
            roundedRect: rect, xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        color.withAlphaComponent(0.16).setFill()
        path.fill()
        text.draw(
            at: NSPoint(x: rect.minX + 5, y: rect.midY - size.height / 2),
            withAttributes: attributes)
        return rect.minX - 5
    }

    // MARK: Mouse

    override func mouseDown(with event: NSEvent) {
        mouseDownAt = convert(event.locationInWindow, from: nil)
        pane?.select(media)
    }

    /// A drag past the slop starts the row's drag session (§4.3: to a track,
    /// or onto the canvas).
    /// A LUT starts none: it is applied as a look, never placed (GR-8).
    override func mouseDragged(with event: NSEvent) {
        guard let origin = mouseDownAt, let pane = pane, entry?.kind != .lut else { return }
        let point = convert(event.locationInWindow, from: nil)
        guard abs(point.x - origin.x) > 3 || abs(point.y - origin.y) > 3 else { return }
        mouseDownAt = nil

        let item = NSPasteboardItem()
        item.setString(String(media), forType: .frameJobMedia)
        let dragged = NSDraggingItem(pasteboardWriter: item)
        dragged.setDraggingFrame(bounds, contents: dragImage())
        // The session carries the id and the pane, so the destination views
        // stay ignorant of both the document and this row.
        MediaDragSession.current = MediaDragSession(
            media: media, source: self,
            drop: { [weak pane, media] destination, target in
                pane?.drop(media, on: destination, target: target) ?? false
            })
        beginDraggingSession(with: [dragged], event: event, source: self)
    }

    override func mouseUp(with event: NSEvent) {
        mouseDownAt = nil
    }

    private func dragImage() -> NSImage {
        let image = NSImage(size: bounds.size)
        image.lockFocus()
        DS.chromeBackground.withAlphaComponent(0.9).setFill()
        NSBezierPath(
            roundedRect: NSRect(origin: .zero, size: bounds.size),
            xRadius: DS.listRowRadius, yRadius: DS.listRowRadius
        ).fill()
        if let entry = entry {
            let attributes: [NSAttributedString.Key: Any] = [
                .font: DS.sans(12), .foregroundColor: DS.textStrong,
            ]
            entry.name.draw(at: NSPoint(x: 8, y: bounds.height / 2 - 8), withAttributes: attributes)
        }
        image.unlockFocus()
        return image
    }

    // MARK: Dragging source

    func draggingSession(
        _ session: NSDraggingSession, sourceOperationMaskFor context: NSDraggingContext
    ) -> NSDragOperation {
        .copy
    }

    func draggingSession(
        _ session: NSDraggingSession, endedAt screenPoint: NSPoint, operation: NSDragOperation
    ) {
        MediaDragSession.current = nil
    }

    // MARK: Context menu

    override func menu(for event: NSEvent) -> NSMenu? {
        let menu = NSMenu()
        // **The menu enables its own rows.** AppKit's automatic validation
        // would ask this view for `validateMenuItem(_:)`, and every row but
        // one is unconditionally live, so turning it off costs nothing and
        // buys a guarantee: a contextual menu is built at the moment of the
        // click, which is the moment the answer is wanted, so the enablement
        // below cannot go stale and does not depend on AppKit choosing to ask.
        // `SilenceSheetController`'s popup records the same rule for a
        // different reason — an enabled state set under `autoenablesItems` is
        // put straight back.
        menu.autoenablesItems = false
        // Two groups: what to do with the file on the timeline, then what to
        // do with the file. The loop shape cannot express a separator, so the
        // groups are two loops with one between them.
        //
        // Reveal in Timeline is DISABLED where the file's only users are
        // inside a nest: a nested clip has no id the TIMELINE's selection can
        // hold (`MediaUsage.swift`), so the item would select nothing and
        // scroll nowhere. That case is exactly the one the pane's old
        // top-level-only usage test could not see. Since road map 2's phase 9
        // there IS a way to reach such a clip — open the nest (⌘↓) and it is
        // at the top level of the view — but that is a different command from
        // this one, which reveals on the timeline.
        for (title, selector) in [
            ("Insert at Playhead", #selector(insertMedia(_:))),
            ("Overwrite at Playhead", #selector(overwriteMedia(_:))),
            ("Reveal in Timeline", #selector(revealInTimeline(_:))),
        ] {
            let item = NSMenuItem(title: title, action: selector, keyEquivalent: "")
            item.target = self
            if selector == #selector(revealInTimeline(_:)) {
                item.isEnabled = pane?.canRevealInTimeline(media) ?? false
            } else if entry?.kind == .lut {
                item.isEnabled = false  // a LUT is not placed (GR-8)
            }
            menu.addItem(item)
        }
        menu.addItem(.separator())
        for (title, selector) in [
            ("Reveal in Finder", #selector(revealMedia(_:))),
            ("Relink…", #selector(relinkMedia(_:))),
            ("Remove", #selector(removeMedia(_:))),
        ] {
            let item = NSMenuItem(title: title, action: selector, keyEquivalent: "")
            item.target = self
            menu.addItem(item)
        }
        return menu
    }

    /// The row knows its own id, so these two place THIS file whatever the
    /// list's selection is — and they select it on the way, so the Edit menu
    /// and the row agree afterwards.
    @objc private func insertMedia(_ sender: Any?) { pane?.place(media, insert: true) }
    @objc private func overwriteMedia(_ sender: Any?) { pane?.place(media, insert: false) }

    /// Select the clips that show this file, and scroll the first one into
    /// view. The pane does both — it is the half that can reach the document
    /// and the editor — and it switches the panel to the Clip tab on the way,
    /// which is the panel's own rule for any changed selection.
    @objc private func revealInTimeline(_ sender: Any?) { pane?.revealInTimeline(media) }

    @objc private func revealMedia(_ sender: Any?) { pane?.reveal(media) }
    @objc private func relinkMedia(_ sender: Any?) { pane?.relink(media) }
    @objc private func removeMedia(_ sender: Any?) { pane?.remove(media) }
}

// MARK: - Dragging a row out of the panel

extension NSPasteboard.PasteboardType {
    /// The private type a media row drags with. Deliberately NOT `.fileURL`:
    /// the editor's root view accepts file URLs and would open the file as a
    /// new document, which is not what dragging a row inside a project means.
    static let frameJobMedia = NSPasteboard.PasteboardType("com.kgalligan.framejob.media")
}

/// What a drop onto a lane does about the room the clip needs (spec §6).
///
/// The modifiers are the timeline's own, read at the moment of the drop:
/// none places the clip and lets the overlap rule refuse it, ⌥ makes room
/// for it and ⇧⌥ takes the room it needs. ⌥ alone is free here — the
/// duplicate-drag it means elsewhere is a gesture on a CLIP, and this drag
/// starts in the media list.
enum MediaDropMode: Equatable {
    case add
    case insert
    case overwrite

    /// The mode the modifiers currently held describe.
    static func current(_ flags: NSEvent.ModifierFlags) -> MediaDropMode {
        guard flags.contains(.option) else { return .add }
        return flags.contains(.shift) ? .overwrite : .insert
    }
}

/// Where a dragged media row landed.
enum MediaDropTarget: Equatable {
    /// A timeline track, at the time under the cursor, and what to do about
    /// what is already there.
    case track(UInt32, Ticks, MediaDropMode)
    /// The preview canvas: a new top track at the playhead (§4.3).
    case canvas
}

/// The media drag in flight. AppKit runs one drag at a time, so one slot is
/// enough — and it is what lets the destination views stay ignorant of the
/// document: they report WHERE the row landed and the pane that started the
/// drag performs the edit.
final class MediaDragSession {
    static var current: MediaDragSession?

    let media: UInt32
    /// The row being dragged; the pane checks its window against the
    /// destination's, so a drag between two open projects cannot edit the
    /// wrong one.
    weak var source: NSView?
    let drop: (NSView, MediaDropTarget) -> Bool

    init(media: UInt32, source: NSView, drop: @escaping (NSView, MediaDropTarget) -> Bool) {
        self.media = media
        self.source = source
        self.drop = drop
    }
}

// MARK: - Drop targets

/// The timeline as a drop target for a media row (§4.3: "drops at the
/// cursor"). Registered by `EditorViewController+Inspector.installInspector`;
/// the arithmetic is `TimelineLayout`'s, as it is for every other point in
/// that view.
extension TimelineView {
    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool {
        guard let session = MediaDragSession.current else { return false }
        let point = content.convert(sender.draggingLocation, from: nil)
        guard let row = layout.row(atY: point.y), let track = track(atRow: row)
        else { return false }
        // `NSDraggingInfo` carries no modifiers, so the flags are read live —
        // which is right anyway: what matters is what is held at the DROP.
        let mode = MediaDropMode.current(
            NSEvent.modifierFlags.intersection(.deviceIndependentFlagsMask))
        return session.drop(
            self, .track(track.id, max(layout.time(atX: point.x), 0), mode))
    }
}

/// The preview canvas as a drop target: a media row dropped here appends on a
/// new top track at the playhead (§4.3).
extension PreviewCanvasView {
    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool {
        guard let session = MediaDragSession.current else { return false }
        return session.drop(self, .canvas)
    }
}

import AppKit

/// One file in the list: thumbnail, name, the meta line, and the audio and
/// missing badges. Drawn rather than composed from controls — a row has no
/// editable field, and drawing keeps a list of dozens cheap.
///
/// The redesign's row is 52 pt with a 34 × 38 thumbnail (handoff README,
/// Part 2 §5). The old one was 56 pt around a 72-wide tile, which read as a
/// strip of filmstrip frames rather than as a list; the narrow portrait well
/// makes the NAME the thing you scan down.
///
/// **Why this is a file of its own.** `MediaPane.swift` stood at 822 lines
/// against app/CLAUDE.md's ~600 cap, and road map 2's phase 8 came to give
/// the Media tab a search field, a sort popup, an "unused only" filter and a
/// Reveal in Timeline context item — so the pane had to give something up
/// before it took any of them on. That is the payment
/// `LayerRenderersText.swift` made in phase 6 and `ExporterSettings.swift`
/// and `ExportSheetOptions.swift` made in phase 7, and it is worth noting
/// that phase 8's four additions landed on BOTH sides of this cut: the three
/// controls are the list's and the context item is a row's, so each half got
/// the room it needed. The room was not ENOUGH — phase 6's warning arriving
/// again, that a cut's estimate is worth about two thirds of the truth — so
/// phase 8c cut a second time, and the row commands the pane keeps are
/// `MediaPaneCommands.swift` now.
///
/// **The cut falls below the DRAG rather than under the row's closing
/// brace**, which is the one decision in it. A row is a drag source (§4.3),
/// and everything that followed it in the old file is there to serve that
/// drag: the private pasteboard type it writes, the two enums that name
/// where it may land, the session that carries it in flight, and the two
/// destination views that report a landing back. Cutting under the class
/// would have left the source in one file and the vocabulary it drags with
/// in another — a seam through the middle of one sentence. What the pane
/// keeps of the drag is the one part a row cannot do: `drop(_:on:target:)`
/// performs the edit, as `select`, `place`, `reveal`, `relink` and `remove`
/// do for the row menu, and every one of those goes through `binding`, which
/// is the pane's business and never a row's. The pane keeps the LIST — its
/// one section, its bands, and the Finder drop onto the panel.
///
/// **Nothing widened**, and that is measured rather than assumed. A type
/// carries its own scope, so every `private` member below keeps the privacy
/// it had — where splitting a TYPE across files costs each crossing member
/// its own, the toll `ExporterLoudness.swift` records and the two
/// `extension ExportSheetController` files pay. The row already reached the
/// pane through internal members and the pane already reached the row
/// through two (`init(media:pane:)` and `invalidateThumbnail()`), so the
/// file boundary changed no declaration at all. It is
/// `ExportProgressSheetController.swift`'s free cut a second time.
final class MediaRowView: NSView, NSDraggingSource {
    static let height: CGFloat = 52

    private static let thumbSize = NSSize(width: 34, height: 38)
    private static let padding: CGFloat = 8
    /// Thumbnail to text, per the design's row.
    private static let gap: CGFloat = 9

    private let media: UInt32
    private weak var pane: MediaPane?
    private var thumbnail: CGImage?
    private var triedThumbnail = false
    private var mouseDownAt: CGPoint?
    private var hovered = false

    /// Whether this row is the document's selected media. Read rather than
    /// stored, because the pane is rebuilt whole whenever the media list
    /// changes and per-row state would not survive it.
    private var selected: Bool { pane?.binding.document?.selectedMedia == media }

    init(media: UInt32, pane: MediaPane) {
        self.media = media
        self.pane = pane
        super.init(frame: .zero)
        wantsLayer = true
        syncToolTip()
    }

    /// The row is a drag source (§4.3) and nothing about it says so. The
    /// list has no room for a line that does, so the row says it itself.
    static let dragHint =
        "Drag to a timeline track, or onto the canvas. Hold ⌥ to insert, ⇧⌥ to overwrite."

    /// The row's tooltip: the drag hint, and above it, for a copy, where the
    /// copy lives (spec §11 #228-O, Q1 and Q2) — the Media tab has no path
    /// line to say it in.
    static func toolTip(for entry: MediaSnapshot) -> String {
        // A LUT is never dragged (spec §11 GR-8): it is applied as a look.
        if entry.kind == .lut { return "A LUT: apply it to clips as a look." }
        guard let original = entry.original else { return dragHint }
        let folder = (entry.path as NSString).deletingLastPathComponent
        let home =
            folder.hasSuffix("/\(AppSupport.folderName)/Rewrapped")
            ? "Frame Job's Rewrapped folder" : "this project's package"
        return "\(original.path) — copied into \(home).\n" + dragHint
    }

    /// Keeps the tooltip current after a relink or a consolidate; written
    /// only when it changed, so the tooltip manager is not reset each pass.
    func syncToolTip() {
        let wanted = entry.map(Self.toolTip(for:)) ?? Self.dragHint
        if toolTip != wanted { toolTip = wanted }
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("MediaRowView does not support NSCoder")
    }

    override var isFlipped: Bool { true }

    override var intrinsicContentSize: NSSize {
        NSSize(width: NSView.noIntrinsicMetric, height: Self.height)
    }

    private var entry: MediaSnapshot? { pane?.binding.snapshot.media(media) }

    func invalidateThumbnail() {
        triedThumbnail = false
        thumbnail = nil
        needsDisplay = true
    }

    /// The cached first-second thumbnail, or a decoded still for an image
    /// file. Loaded once per row: `MediaImporter` posts when a cache lands and
    /// `invalidateThumbnail()` asks for it again.
    private func loadThumbnailIfNeeded() {
        guard !triedThumbnail else { return }
        triedThumbnail = true
        guard let pane = pane, let entry = entry else { return }
        if let cache = pane.binding.document?.cacheDirectory,
           let image = MediaImporter.loadThumbnail(for: media, index: 0, in: cache)
        {
            thumbnail = image
            return
        }
        // An HLG or PQ still waits for its tile, never ImageIO's tone map (spec §11 HD-21).
        guard entry.kind == .image, let url = mediaURL(for: entry),
            StillColor.conversion(at: url) == nil
        else { return }
        thumbnail = MediaImporter.decodeImage(url, maxPixelSize: 256)
    }

    // MARK: Hover

    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // ONLY this view's own areas. `toolTip` is implemented as a tracking
        // area owned by `NSToolTipManager`, and it is in `trackingAreas` like
        // any other: the usual `trackingAreas.forEach(removeTrackingArea)`
        // deletes it on the first layout pass — which in an autolayout stack
        // inside a scroll view is immediately — and nothing ever puts it back,
        // so the row's one statement that it is a drag source never appears.
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        // `.inVisibleRect` keeps the area right as the list scrolls under the
        // pointer; the rect argument is then ignored.
        addTrackingArea(
            NSTrackingArea(
                rect: bounds,
                options: [.mouseEnteredAndExited, .activeInKeyWindow, .inVisibleRect],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) {
        hovered = true
        needsDisplay = true
    }

    override func mouseExited(with event: NSEvent) {
        hovered = false
        needsDisplay = true
    }

    // MARK: Drawing

    override func draw(_ dirtyRect: NSRect) {
        guard let entry = entry else { return }
        loadThumbnailIfNeeded()
        let missing = mediaURL(for: entry) == nil

        // A row is an object now, not a band with a rule under it: one
        // hairline box on the list-row radius, and the hover fill inside the
        // same shape so the two never disagree by half a pixel.
        let box = NSBezierPath(
            roundedRect: bounds.insetBy(dx: 0.5, dy: 0.5),
            xRadius: DS.listRowRadius, yRadius: DS.listRowRadius)
        if selected {
            DS.accent.withAlphaComponent(0.14).setFill()
            box.fill()
        } else if hovered {
            DS.hoverFill.setFill()
            box.fill()
        }
        (selected ? DS.accent : DS.border).setStroke()
        box.stroke()

        let thumb = NSRect(
            x: Self.padding, y: ((bounds.height - Self.thumbSize.height) / 2).rounded(),
            width: Self.thumbSize.width, height: Self.thumbSize.height)
        let well = NSBezierPath(
            roundedRect: thumb, xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        NSColor.controlBackgroundColor.setFill()
        well.fill()
        if let image = thumbnail {
            // Aspect FILL, clipped to the well: the well is portrait and most
            // footage is not, so fitting would leave a 34 × 19 stamp floating
            // in a box twice its height.
            NSGraphicsContext.current?.saveGraphicsState()
            well.addClip()
            let scale = max(
                thumb.width / CGFloat(image.width), thumb.height / CGFloat(image.height))
            let size = CGSize(
                width: CGFloat(image.width) * scale, height: CGFloat(image.height) * scale)
            TimelineDraw.image(
                image,
                in: CGRect(
                    x: thumb.midX - size.width / 2, y: thumb.midY - size.height / 2,
                    width: size.width, height: size.height))
            NSGraphicsContext.current?.restoreGraphicsState()
        } else {
            TimelineDraw.symbol(
                entry.kind == .audio ? "waveform" : entry.kind == .lut ? "cube" : "photo",
                fallback: "▦", in: thumb,
                tint: DS.textFaint)
        }
        DS.border.setStroke()
        NSBezierPath(
            roundedRect: thumb.insetBy(dx: 0.5, dy: 0.5), xRadius: DS.controlRadius,
            yRadius: DS.controlRadius
        ).stroke()

        // The badges moved to the trailing edge: a 52 pt row has no third
        // line to hang them under, and "missing" is the one thing in this
        // list that must never be the part that got cropped.
        var trailing = bounds.maxX - Self.padding
        if missing {
            trailing = drawBadge("missing", endingAt: trailing, color: DS.coral)
        }
        if entry.hasAudio {
            trailing = drawBadge("audio", endingAt: trailing, color: DS.clipAudio)
        }

        let textX = thumb.maxX + Self.gap
        let width = max(trailing - textX, 10)
        // Truncating, not clipping: the meta line is longer than the space a
        // row with badges leaves ("00:00:21:00 · 1080×1920 · 25 fps" against
        // about 150 pt), and `TimelineDraw.label` would cut it mid-glyph — an
        // ellipsis at least says that something was left out.
        TimelineDraw.truncated(
            entry.name, in: CGRect(x: textX, y: 11, width: width, height: 16),
            font: DS.sans(12), color: DS.textStrong)
        TimelineDraw.truncated(
            metaLine(entry), in: CGRect(x: textX, y: 28, width: width, height: 13),
            font: DS.mono(10), color: DS.textMuted)
    }

    private func metaLine(_ entry: MediaSnapshot) -> String {
        var parts: [String] = []
        if entry.duration > 0 {
            parts.append(
                ReelTime.format(entry.duration, fps: entry.fps, frames: true))
        }
        if entry.width > 0, entry.height > 0 {
            parts.append("\(entry.width)×\(entry.height)")
        }
        if entry.hasVideo, entry.fps.double > 0 {
            parts.append("\(entry.fps.displayName) fps")
        }
        if parts.isEmpty { parts.append(entry.kind.displayName) }
        return parts.joined(separator: " · ")
    }

    /// One trailing badge, laid out right to left; returns the x the NEXT one
    /// should end at, so a row with both stacks them inward.
    @discardableResult
    private func drawBadge(_ text: String, endingAt x: CGFloat, color: NSColor) -> CGFloat {
        let attributes: [NSAttributedString.Key: Any] = [
            .font: DS.mono(9), .foregroundColor: color,
        ]
        let size = text.size(withAttributes: attributes)
        let width = size.width + 10
        let rect = NSRect(x: x - width, y: bounds.midY - 6.5, width: width, height: 13)
        let path = NSBezierPath(
            roundedRect: rect, xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        color.withAlphaComponent(0.16).setFill()
        path.fill()
        text.draw(
            at: NSPoint(x: rect.minX + 5, y: rect.midY - size.height / 2),
            withAttributes: attributes)
        return rect.minX - 5
    }

    // MARK: Mouse

    override func mouseDown(with event: NSEvent) {
        mouseDownAt = convert(event.locationInWindow, from: nil)
        pane?.select(media)
    }

    /// A drag past the slop starts the row's drag session (§4.3: to a track,
    /// or onto the canvas).
    /// A LUT starts none: it is applied as a look, never placed (GR-8).
    override func mouseDragged(with event: NSEvent) {
        guard let origin = mouseDownAt, let pane = pane, entry?.kind != .lut else { return }
        let point = convert(event.locationInWindow, from: nil)
        guard abs(point.x - origin.x) > 3 || abs(point.y - origin.y) > 3 else { return }
        mouseDownAt = nil

        let item = NSPasteboardItem()
        item.setString(String(media), forType: .frameJobMedia)
        let dragged = NSDraggingItem(pasteboardWriter: item)
        dragged.setDraggingFrame(bounds, contents: dragImage())
        // The session carries the id and the pane, so the destination views
        // stay ignorant of both the document and this row.
        MediaDragSession.current = MediaDragSession(
            media: media, source: self,
            drop: { [weak pane, media] destination, target in
                pane?.drop(media, on: destination, target: target) ?? false
            })
        beginDraggingSession(with: [dragged], event: event, source: self)
    }

    override func mouseUp(with event: NSEvent) {
        mouseDownAt = nil
    }

    private func dragImage() -> NSImage {
        let image = NSImage(size: bounds.size)
        image.lockFocus()
        DS.chromeBackground.withAlphaComponent(0.9).setFill()
        NSBezierPath(
            roundedRect: NSRect(origin: .zero, size: bounds.size),
            xRadius: DS.listRowRadius, yRadius: DS.listRowRadius
        ).fill()
        if let entry = entry {
            let attributes: [NSAttributedString.Key: Any] = [
                .font: DS.sans(12), .foregroundColor: DS.textStrong,
            ]
            entry.name.draw(at: NSPoint(x: 8, y: bounds.height / 2 - 8), withAttributes: attributes)
        }
        image.unlockFocus()
        return image
    }

    // MARK: Dragging source

    func draggingSession(
        _ session: NSDraggingSession, sourceOperationMaskFor context: NSDraggingContext
    ) -> NSDragOperation {
        .copy
    }

    func draggingSession(
        _ session: NSDraggingSession, endedAt screenPoint: NSPoint, operation: NSDragOperation
    ) {
        MediaDragSession.current = nil
    }

    // MARK: Context menu

    override func menu(for event: NSEvent) -> NSMenu? {
        let menu = NSMenu()
        // **The menu enables its own rows.** AppKit's automatic validation
        // would ask this view for `validateMenuItem(_:)`, and every row but
        // one is unconditionally live, so turning it off costs nothing and
        // buys a guarantee: a contextual menu is built at the moment of the
        // click, which is the moment the answer is wanted, so the enablement
        // below cannot go stale and does not depend on AppKit choosing to ask.
        // `SilenceSheetController`'s popup records the same rule for a
        // different reason — an enabled state set under `autoenablesItems` is
        // put straight back.
        menu.autoenablesItems = false
        // Two groups: what to do with the file on the timeline, then what to
        // do with the file. The loop shape cannot express a separator, so the
        // groups are two loops with one between them.
        //
        // Reveal in Timeline is DISABLED where the file's only users are
        // inside a nest: a nested clip has no id the TIMELINE's selection can
        // hold (`MediaUsage.swift`), so the item would select nothing and
        // scroll nowhere. That case is exactly the one the pane's old
        // top-level-only usage test could not see. Since road map 2's phase 9
        // there IS a way to reach such a clip — open the nest (⌘↓) and it is
        // at the top level of the view — but that is a different command from
        // this one, which reveals on the timeline.
        for (title, selector) in [
            ("Insert at Playhead", #selector(insertMedia(_:))),
            ("Overwrite at Playhead", #selector(overwriteMedia(_:))),
            ("Reveal in Timeline", #selector(revealInTimeline(_:))),
        ] {
            let item = NSMenuItem(title: title, action: selector, keyEquivalent: "")
            item.target = self
            if selector == #selector(revealInTimeline(_:)) {
                item.isEnabled = pane?.canRevealInTimeline(media) ?? false
            } else if entry?.kind == .lut {
                item.isEnabled = false  // a LUT is not placed (GR-8)
            }
            menu.addItem(item)
        }
        menu.addItem(.separator())
        for (title, selector) in [
            ("Reveal in Finder", #selector(revealMedia(_:))),
            ("Relink…", #selector(relinkMedia(_:))),
            ("Remove", #selector(removeMedia(_:))),
        ] {
            let item = NSMenuItem(title: title, action: selector, keyEquivalent: "")
            item.target = self
            menu.addItem(item)
        }
        return menu
    }

    /// The row knows its own id, so these two place THIS file whatever the
    /// list's selection is — and they select it on the way, so the Edit menu
    /// and the row agree afterwards.
    @objc private func insertMedia(_ sender: Any?) { pane?.place(media, insert: true) }
    @objc private func overwriteMedia(_ sender: Any?) { pane?.place(media, insert: false) }

    /// Select the clips that show this file, and scroll the first one into
    /// view. The pane does both — it is the half that can reach the document
    /// and the editor — and it switches the panel to the Clip tab on the way,
    /// which is the panel's own rule for any changed selection.
    @objc private func revealInTimeline(_ sender: Any?) { pane?.revealInTimeline(media) }

    @objc private func revealMedia(_ sender: Any?) { pane?.reveal(media) }
    @objc private func relinkMedia(_ sender: Any?) { pane?.relink(media) }
    @objc private func removeMedia(_ sender: Any?) { pane?.remove(media) }
}

// MARK: - Dragging a row out of the panel

extension NSPasteboard.PasteboardType {
    /// The private type a media row drags with. Deliberately NOT `.fileURL`:
    /// the editor's root view accepts file URLs and would open the file as a
    /// new document, which is not what dragging a row inside a project means.
    static let frameJobMedia = NSPasteboard.PasteboardType("com.kgalligan.framejob.media")
}

/// What a drop onto a lane does about the room the clip needs (spec §6).
///
/// The modifiers are the timeline's own, read at the moment of the drop:
/// none places the clip and lets the overlap rule refuse it, ⌥ makes room
/// for it and ⇧⌥ takes the room it needs. ⌥ alone is free here — the
/// duplicate-drag it means elsewhere is a gesture on a CLIP, and this drag
/// starts in the media list.
enum MediaDropMode: Equatable {
    case add
    case insert
    case overwrite

    /// The mode the modifiers currently held describe.
    static func current(_ flags: NSEvent.ModifierFlags) -> MediaDropMode {
        guard flags.contains(.option) else { return .add }
        return flags.contains(.shift) ? .overwrite : .insert
    }
}

/// Where a dragged media row landed.
enum MediaDropTarget: Equatable {
    /// A timeline track, at the time under the cursor, and what to do about
    /// what is already there.
    case track(UInt32, Ticks, MediaDropMode)
    /// The preview canvas: a new top track at the playhead (§4.3).
    case canvas
}

/// The media drag in flight. AppKit runs one drag at a time, so one slot is
/// enough — and it is what lets the destination views stay ignorant of the
/// document: they report WHERE the row landed and the pane that started the
/// drag performs the edit.
final class MediaDragSession {
    static var current: MediaDragSession?

    let media: UInt32
    /// The row being dragged; the pane checks its window against the
    /// destination's, so a drag between two open projects cannot edit the
    /// wrong one.
    weak var source: NSView?
    let drop: (NSView, MediaDropTarget) -> Bool

    init(media: UInt32, source: NSView, drop: @escaping (NSView, MediaDropTarget) -> Bool) {
        self.media = media
        self.source = source
        self.drop = drop
    }
}

// MARK: - Drop targets

/// The timeline as a drop target for a media row (§4.3: "drops at the
/// cursor"). Registered by `EditorViewController+Inspector.installInspector`;
/// the arithmetic is `TimelineLayout`'s, as it is for every other point in
/// that view.
extension TimelineView {
    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool {
        guard let session = MediaDragSession.current else { return false }
        let point = content.convert(sender.draggingLocation, from: nil)
        guard let row = layout.row(atY: point.y), let track = track(atRow: row)
        else { return false }
        // `NSDraggingInfo` carries no modifiers, so the flags are read live —
        // which is right anyway: what matters is what is held at the DROP.
        let mode = MediaDropMode.current(
            NSEvent.modifierFlags.intersection(.deviceIndependentFlagsMask))
        return session.drop(
            self, .track(track.id, max(layout.time(atX: point.x), 0), mode))
    }
}

/// The preview canvas as a drop target: a media row dropped here appends on a
/// new top track at the playhead (§4.3).
extension PreviewCanvasView {
    override func draggingEntered(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func draggingUpdated(_ sender: any NSDraggingInfo) -> NSDragOperation {
        MediaDragSession.current == nil ? [] : .copy
    }

    override func performDragOperation(_ sender: any NSDraggingInfo) -> Bool {
        guard let session = MediaDragSession.current else { return false }
        return session.drop(self, .canvas)
    }
}

import AppKit

/// The missing-media dialog (spec §5.6, §10 step 12): every media entry whose
/// file is gone, with a Locate… beside it, committed as one undo step.
///
/// A project ALWAYS opens, missing files or not — the clips stay, the
/// compositor draws a slate over them and the plan holds their time empty —
/// so this is an offer, never a gate. `EditorViewController+Export.swift`
/// puts it up once per document when a window with missing media appears; the
/// Media tab's per-row Relink… (`MediaPane.swift`) is the same op reached one
/// file at a time.
///
/// Picking one file also OFFERS its folder to the others: a moved shoot is
/// one folder with all of it in, and matching by file name there turns twenty
/// Locate… trips into one. Nothing is matched silently in a folder the user
/// did not just point at.
final class RelinkSheetController: NSViewController {
    /// Weak: a dialog must never keep a closing document alive.
    private weak var document: ProjectDocument?
    /// The missing entries as the sheet opened. The sheet blocks every edit
    /// while it is up, so this list cannot go stale under it.
    private let missing: [MediaSnapshot]
    /// media id → the file the user chose for it. Applied on Apply, not on
    /// pick, so Cancel really does leave the project untouched.
    private var replacements: [UInt32: URL] = [:]
    private var rows: [RelinkRowView] = []
    private var applyButton: NSButton!

    /// Documents this sheet has already been offered for. A WEAK set: an
    /// `ObjectIdentifier` of a closed document can be reused by the next one
    /// allocated at the same address, which would silently skip the offer for
    /// a project that needed it.
    private static let offered = NSHashTable<ProjectDocument>.weakObjects()

    /// True the first time it is asked about a document, false ever after —
    /// the automatic offer happens once per open, not on every window
    /// activation.
    static func markOffered(_ document: ProjectDocument) -> Bool {
        if offered.contains(document) { return false }
        offered.add(document)
        return true
    }

    /// Row height and the tallest the list grows before it scrolls.
    static let rowHeight: CGFloat = 46
    static let maxListHeight: CGFloat = 232

    init(document: ProjectDocument) {
        self.document = document
        self.missing = document.missingMedia
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("RelinkSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        let list = NSStackView()
        list.orientation = .vertical
        list.alignment = .leading
        list.spacing = 0
        list.translatesAutoresizingMaskIntoConstraints = false
        for media in missing {
            let row = RelinkRowView(media: media, sheet: self)
            rows.append(row)
            list.addArrangedSubview(row)
            row.widthAnchor.constraint(equalTo: list.widthAnchor).isActive = true
        }

        let scroll = NSScrollView()
        scroll.hasVerticalScroller = true
        scroll.drawsBackground = false
        scroll.borderType = .noBorder
        scroll.translatesAutoresizingMaskIntoConstraints = false
        scroll.documentView = list
        let width = sheetWidth - sheetInset * 2
        let height = min(
            Self.maxListHeight, max(Self.rowHeight, CGFloat(missing.count) * Self.rowHeight))
        NSLayoutConstraint.activate([
            scroll.widthAnchor.constraint(equalToConstant: width),
            scroll.heightAnchor.constraint(equalToConstant: height),
            list.leadingAnchor.constraint(equalTo: scroll.contentView.leadingAnchor),
            list.trailingAnchor.constraint(equalTo: scroll.contentView.trailingAnchor),
            list.topAnchor.constraint(equalTo: scroll.contentView.topAnchor),
        ])

        let cancelButton = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        applyButton = StickerButton(
            title: "Relink", style: .primary, target: self, action: #selector(applyClicked(_:)))
        let count = missing.count == 1 ? "1 file" : "\(missing.count) files"
        view = makeSheetView(
            title: "Missing media",
            hint: "The project opened without these files: their clips keep their place on the "
                + "timeline and show a slate until the files are found.",
            content: scroll,
            buttonRow: makeButtonRow(
                cancel: cancelButton, apply: applyButton, leading: [sheetFootnote(count)]))
        syncApply()
    }

    private func syncApply() {
        applyButton?.isEnabled = !replacements.isEmpty
    }

    // MARK: - Locating

    /// The Locate… panel for one row. Presented on the SHEET's window, so the
    /// dialog the user is answering stays put behind it.
    func locate(_ media: UInt32) {
        guard let entry = missing.first(where: { $0.id == media }), let window = view.window
        else {
            NSSound.beep()
            return
        }
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        panel.message = "Choose the file for “\(entry.name)”."
        panel.beginSheetModal(for: window) { [weak self] response in
            guard response == .OK, let url = panel.url, let self = self else { return }
            self.chose(url, for: media)
        }
    }

    /// Records one choice and offers the rest of the folder to the entries
    /// still unmatched. Only a file that exists AND is not already spoken for
    /// is taken. Internal so a probe chooses without the Locate… panel.
    func chose(_ url: URL, for media: UInt32) {
        replacements[media] = url
        let folder = url.deletingLastPathComponent()
        for entry in missing where entry.id != media && replacements[entry.id] == nil {
            let candidate = folder.appendingPathComponent(entry.name)
            guard FileManager.default.fileExists(atPath: candidate.path) else { continue }
            replacements[entry.id] = candidate
        }
        for row in rows {
            row.update(replacements[row.media])
        }
        syncApply()
    }

    // MARK: - Commit

    @objc private func cancelClicked(_ sender: Any?) {
        dismiss(self)
    }

    /// Every chosen file, in id order, through `ProjectDocument.relinkMedia`
    /// (spec §11, #63): each is probed as import probes it, so an entry takes
    /// its file's duration, size, rate and flags and a clip past a shorter
    /// file's end is held to it; every probed relink is ONE undo step, and a
    /// cache pass follows — a different file rebuilds, the same file moved
    /// elsewhere is skipped (the stamp has no path), and so is every other
    /// media whose marker still matches. A file of another kind is refused
    /// in the core's sentence, and each refused sentence is alerted after
    /// the grouped edit, in order, even when another relink applied (#180).
    @objc private func applyClicked(_ sender: Any?) {
        let replacements = self.replacements
        let document = self.document
        dismiss(self)
        guard let document = document, !replacements.isEmpty else { return }
        let choices = replacements.keys.sorted().compactMap { id -> (media: UInt32, url: URL)? in
            guard let url = replacements[id] else { return nil }
            return (media: id, url: url)
        }
        document.relinkMedia(choices, alertingRefusals: true)
    }
}

// MARK: - One row

/// One missing file: its name, where it was, and a Locate… button that turns
/// into the chosen path once a file has been picked.
///
/// It knows only its media id and asks the sheet to do everything — the
/// pattern every list row in this app follows (`MediaRowView`), so a row can
/// never hold a stale copy of a value the document owns.
final class RelinkRowView: NSView {
    let media: UInt32
    private weak var sheet: RelinkSheetController?
    private let nameLabel = NSTextField(labelWithString: "")
    private let pathLabel = NSTextField(labelWithString: "")
    private let locateButton: NSButton

    init(media: MediaSnapshot, sheet: RelinkSheetController) {
        self.media = media.id
        self.sheet = sheet
        // Target and action are set below: `self` does not exist yet here.
        self.locateButton = StickerButton(
            title: "Locate…", style: .secondary, target: nil, action: nil)
        super.init(frame: .zero)
        translatesAutoresizingMaskIntoConstraints = false

        nameLabel.stringValue = media.name
        nameLabel.font = DS.sans(13, weight: .semibold)
        nameLabel.textColor = DS.textStrong
        nameLabel.lineBreakMode = .byTruncatingMiddle

        pathLabel.stringValue = media.path
        pathLabel.font = DS.mono(10)
        pathLabel.textColor = DS.textFaint
        pathLabel.lineBreakMode = .byTruncatingHead
        // A label resists compression by default, which would push the
        // Locate… button off the card instead of shortening the path.
        for label in [nameLabel, pathLabel] {
            label.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
            label.setContentHuggingPriority(.defaultLow, for: .horizontal)
        }

        locateButton.target = self
        locateButton.action = #selector(locateClicked(_:))

        let text = NSStackView(views: [nameLabel, pathLabel])
        text.orientation = .vertical
        text.alignment = .leading
        text.spacing = 1
        text.translatesAutoresizingMaskIntoConstraints = false
        locateButton.translatesAutoresizingMaskIntoConstraints = false
        addSubview(text)
        addSubview(locateButton)
        NSLayoutConstraint.activate([
            heightAnchor.constraint(equalToConstant: RelinkSheetController.rowHeight),
            text.leadingAnchor.constraint(equalTo: leadingAnchor),
            text.centerYAnchor.constraint(equalTo: centerYAnchor),
            text.trailingAnchor.constraint(
                lessThanOrEqualTo: locateButton.leadingAnchor, constant: -10),
            locateButton.trailingAnchor.constraint(equalTo: trailingAnchor),
            locateButton.centerYAnchor.constraint(equalTo: centerYAnchor),
        ])
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("RelinkRowView does not support NSCoder")
    }

    /// Repaints from the sheet's decision: the chosen path in the strong ink,
    /// the old one faint. Called on EVERY row after any pick, because one
    /// pick can match several rows at once.
    func update(_ replacement: URL?) {
        guard let replacement = replacement else { return }
        pathLabel.stringValue = replacement.path
        pathLabel.textColor = DS.textMuted
        locateButton.title = "Change…"
    }

    override func draw(_ dirtyRect: NSRect) {
        DS.border.setFill()
        NSRect(x: 0, y: 0, width: bounds.width, height: 1).fill()
    }

    @objc private func locateClicked(_ sender: Any?) {
        sheet?.locate(media)
    }
}
//! `relink_media` — spec §6, table "Tracks, markers, canvas, media", and
//! spec §11 #63.
//!
//! A relink points a media at another file: Relink… after the original
//! moved (spec §5.6), the missing-media sheet, or the tool. Given the new
//! file's PROBE — the descriptor `MediaImporter.probe` answers, minus `path`
//! and `bookmark` — the record takes its duration, size, rate and flags, a
//! file of another kind is refused, and every media clip of it whose window
//! now runs past a SHORTER file's end is held to it. Without a probe the
//! record is kept: Consolidate and the open-time re-anchor point at a copy
//! of the same file. A probe's `original` (spec §11 #228-O) replaces the
//! stored one, so a probe without one clears it, and no probe keeps it. A
//! probe never carries `color`, and a relink keeps the media's Camera Log
//! (spec §11 GR-16): it is the person's reading of the footage, which a new
//! path to the same footage does not change. A probe's `cursor` replaces the
//! stored one as `original` does (spec §11 CU-39). A probe never carries `speech`
//! either; a probed relink clips the stored spans to the new file or clears
//! them (spec §11 AU-116).
//!
//! Cut out of `edit_track.rs`, which keeps the media list's other two ops
//! and the two things this one shares with `add_media`: `MEDIA_KEYS` and
//! `check_media_fields`, so a probe is checked in the same words a
//! descriptor is.

use std::mem;

use serde_json::Value;

use crate::edit_track::{check_media_fields, normalize_original, MEDIA_KEYS};
use crate::export::describe;
use crate::export_overrides::spelled;
use crate::model::{Clip, Media, Project, Source};
use crate::outcome::Outcome;
use crate::source_window::SourceBound;
use crate::time::Ticks;

impl Project {
    /// Points a media at a new file, and — given its `probe` — takes the
    /// file's facts (spec §11 #63).
    ///
    /// A `bookmark` of `None` CLEARS the stored one rather than keeping it:
    /// a bookmark resolves to the file it was made from, so the old one
    /// would point straight back at the file the user is replacing.
    ///
    /// Answers, in order: `Err` for an unknown media or an empty path; `Err`
    /// for a probe that is not an object, that carries a key outside the
    /// descriptor's (or `path` or `bookmark`, which are this op's own
    /// arguments, or `color`, which a relink keeps), that does not match the
    /// schema, or whose fields
    /// `add_media` would refuse; then a REFUSAL for a file of another kind,
    /// because each clip's source kind was chosen from it.
    ///
    /// A probed relink writes `duration`, `width`, `height`, `fps`, the
    /// three flags and `original` (none in the probe clears it), then
    /// holds each `media`-source clip of this media — on the timeline and
    /// in every stored nest, orphans included — whose
    /// duration exceeds the window the file now holds to
    /// `duration_resnapped` (D4-4): on the grid, at least one frame, the
    /// frame floor winning for a clip whose `in` is past the new end.
    /// Everything else on the clip is kept, as `trim_end` keeps it; a still
    /// keeps its `at`; the overlap rule is not re-checked (D7-3).
    pub fn relink_media(
        &self,
        media: u32,
        path: &str,
        bookmark: Option<&str>,
        probe: Option<&Value>,
    ) -> Result<Outcome, String> {
        let old_kind = self.require_media(media)?.kind;
        let path = path.trim();
        if path.is_empty() {
            return Err("media path must not be empty".to_string());
        }
        let probed = match probe {
            Some(probe) => Some(read_probe(media, path, probe)?),
            None => None,
        };
        if let Some(new) = &probed {
            if new.kind != old_kind {
                return Ok(Outcome::Refused(format!(
                    "media {media} is {} media and {path} is {}: relink it to a file of the \
                     same kind, or import this one as new media",
                    spelled(old_kind),
                    spelled(new.kind)
                )));
            }
        }

        let mut next = self.clone();
        if let Some(found) = next.media.iter_mut().find(|m| m.id == media) {
            found.path = path.to_string();
            found.bookmark = bookmark
                .map(str::trim)
                .filter(|given| !given.is_empty())
                .map(|given| given.to_string());
            if let Some(new) = &probed {
                found.duration = new.duration;
                found.width = new.width;
                found.height = new.height;
                found.fps = new.fps;
                found.has_video = new.has_video;
                found.has_audio = new.has_audio;
                found.has_alpha = new.has_alpha;
                found.original = new.original.clone();
                found.cursor = new.cursor.clone();
                found.speech = clipped_speech(found.speech.take(), new);
            }
        }
        if probed.is_some() {
            // Each list is taken out for the walk so a clip's window can be
            // measured against the whole project, the new record included —
            // `edit_canvas.rs`'s `resnap` pattern, every stored nest once.
            let mut clips = mem::take(&mut next.clips);
            next.hold_to_file(&mut clips, media);
            next.clips = clips;
            for index in 0..next.nests.len() {
                let mut clips = mem::take(&mut next.nests[index].clips);
                next.hold_to_file(&mut clips, media);
                next.nests[index].clips = clips;
            }
        }
        self.finish(next)
    }

    /// Holds every `media`-source clip of `media` in `clips` whose duration
    /// runs past the window its file holds, through `source_window.rs`'s
    /// one re-snap of a media duration.
    fn hold_to_file(&self, clips: &mut [Clip], media: u32) {
        for clip in clips.iter_mut() {
            if !matches!(clip.source, Source::Media { media: id, .. } if id == media) {
                continue;
            }
            if let SourceBound::Timeline(bound) = self.source_length_on_timeline(clip) {
                if clip.duration > bound {
                    clip.duration = self.duration_resnapped(clip);
                }
            }
        }
    }
}

/// A probed relink's `speech` (spec §11 AU-116): the stored spans held to
/// the new file — a span starting at or past its `duration` dropped, an end
/// past it clamped — and `None` when none is left or the file has no audio,
/// so `finish`'s `validate` never refuses a relink over spans. The spans are
/// not detected again.
fn clipped_speech(speech: Option<Vec<[Ticks; 2]>>, file: &Media) -> Option<Vec<[Ticks; 2]>> {
    if !file.has_audio {
        return None;
    }
    let kept: Vec<[Ticks; 2]> = speech?
        .into_iter()
        .filter(|[start, _]| *start < file.duration)
        .map(|[start, end]| [start, end.min(file.duration)])
        .collect();
    (!kept.is_empty()).then_some(kept)
}

/// A relink's probe read as a media record, or the `Err` naming what is
/// wrong with it — the Interfaces order of spec §11 #63: not an object, an
/// unknown key, the schema, then `add_media`'s field checks.
fn read_probe(media: u32, path: &str, probe: &Value) -> Result<Media, String> {
    let Value::Object(fields) = probe else {
        return Err(format!(
            "a relink probe must be a json object, not {}",
            describe(probe)
        ));
    };
    for key in fields.keys() {
        if !MEDIA_KEYS.contains(&key.as_str())
            || key == "path"
            || key == "bookmark"
            || key == "color"
        {
            return Err(format!("unknown key \"{key}\" in a relink probe"));
        }
    }
    // Deserialized through `Media` itself, as `add_media` does, so the
    // probe's schema is the model's schema with no second spelling of it.
    let mut record = fields.clone();
    record.insert("id".to_string(), Value::from(media));
    record.insert("path".to_string(), Value::from(path));
    let mut record: Media = serde_json::from_value(Value::Object(record))
        .map_err(|e| format!("relink probe does not match the schema: {e}"))?;
    record.original = normalize_original(record.original);
    check_media_fields(&record)?;
    Ok(record)
}
import Foundation

/// A movie's cursor file at import and relink (road map creator-jobs CU3b, spec §11 CU-34,
/// CU-38): the header read, the attach check, the look beside a probed movie, and the relink
/// rule. A file is attached only when it opens through `ReelCursor` (the open is the check,
/// CU-15) and its `movie_size` equals the probe's `width` × `height`. Await-free and names no
/// `rc_*` (CJ-8 (l)).
extension MediaImporter {
    /// The three header keys the attach reads; the rest of the body is the core's to check.
    struct CursorFileHeader: Decodable, Equatable {
        let inPicture: Bool
        let movieSize: [Int]
        let cursorImage: String

        enum CodingKeys: String, CodingKey {
            case inPicture = "in_picture"
            case movieSize = "movie_size"
            case cursorImage = "cursor_image"
        }
    }

    /// What an attached file gives its media and its recording segment: `media.cursor`
    /// (CU-34 (b)) and the header's `cursor_image`.
    struct CursorAttachment: Equatable {
        let cursor: MediaCursor
        let image: CursorImageMode?
    }

    /// Opens `file` through `ReelCursor(data:)` (the check), then decodes its header, and
    /// attaches it to `descriptor` only when that is a video with pictures whose `width` ×
    /// `height` equal `movie_size` (CU-34). The failure is a sentence naming the file.
    static func cursorAttachment(at file: URL, to descriptor: MediaDescriptor)
        -> Result<CursorAttachment, CursorFileProblem>
    {
        let name = file.lastPathComponent
        let body: Data
        do {
            body = try Data(contentsOf: file)
        } catch {
            return .failure(
                CursorFileProblem(
                    message: "The cursor file \(name) could not be read: "
                        + "\(error.localizedDescription)."))
        }
        do {
            _ = try ReelCursor(data: body)
        } catch {
            let reason = (error as? ReelCoreError)?.message ?? error.localizedDescription
            return .failure(
                CursorFileProblem(message: "The cursor file \(name) was not attached: \(reason)"))
        }
        let header: CursorFileHeader
        do {
            header = try JSONDecoder().decode(CursorFileHeader.self, from: body)
        } catch {
            return .failure(
                CursorFileProblem(
                    message: "The cursor file \(name) could not be read: "
                        + "\(error.localizedDescription)."))
        }
        guard descriptor.kind == .video, descriptor.hasVideo else {
            let movie = URL(fileURLWithPath: descriptor.path).lastPathComponent
            return .failure(
                CursorFileProblem(
                    message: "The cursor file \(name) was not attached: \(movie) has no picture."))
        }
        guard header.movieSize == [descriptor.width, descriptor.height] else {
            let stored = header.movieSize.map(String.init).joined(separator: " × ")
            return .failure(
                CursorFileProblem(
                    message: "The cursor file \(name) was not attached: its movie_size is "
                        + "\(stored) and the movie is \(descriptor.width) × "
                        + "\(descriptor.height)."))
        }
        let cursor = MediaCursor(
            path: file.path, bookmark: bookmarkString(for: file), inPicture: header.inPicture)
        return .success(
            CursorAttachment(cursor: cursor, image: CursorImageMode(rawValue: header.cursorImage)))
    }

    /// `descriptor` with `cursor` from `<stem>.fjcursor` beside `movie` when that file exists
    /// and attaches (CU-34 (a)); otherwise `descriptor` unchanged, and nothing said.
    static func withCursorBeside(_ descriptor: MediaDescriptor, movie: URL) -> MediaDescriptor {
        let file = CursorFileWriter.url(forMovie: movie)
        guard FileManager.default.fileExists(atPath: file.path),
            case .success(let attachment) = cursorAttachment(at: file, to: descriptor)
        else { return descriptor }
        var attached = descriptor
        attached.cursor = attachment.cursor
        return attached
    }

    /// A probed relink's descriptor (CU-38 (a)): `probed` when it carries a cursor (the file
    /// beside the new movie); else, for a video probe with pictures whose `width` × `height`
    /// equal `current`'s, `probed` with `current.cursor` verbatim when `cursorURL(for:)` names a
    /// file that exists; else `probed`, whose missing cursor clears the stored one (CU-39). No
    /// parse — sizes and a file-exists check — so it may run on main.
    static func relinkProbe(_ probed: MediaDescriptor, current: MediaSnapshot?) -> MediaDescriptor
    {
        guard probed.cursor == nil, let current, let kept = current.cursor,
            probed.kind == .video, probed.hasVideo,
            probed.width == current.width, probed.height == current.height,
            let file = cursorURL(for: current),
            FileManager.default.fileExists(atPath: file.path)
        else { return probed }
        var keeping = probed
        keeping.cursor = kept
        return keeping
    }
}
        media.kind == .video && media.hasVideo
    }

    /// Whether the section is shown for a project's media list (CU-54).
    static func showsCursorSection(_ media: [MediaSnapshot]) -> Bool {
        media.contains(where: takesCursor)
    }

    /// Whether a media's cursor file names nothing on disk.
    static func cursorMissing(_ media: MediaSnapshot) -> Bool {
        guard media.cursor != nil else { return false }
        guard let url = cursorURL(for: media) else { return true }
        return !FileManager.default.fileExists(atPath: url.path)
    }

    /// The readout's line (CU-54): nothing selected that can carry one, no
    /// file, the file's name, or its name and that it is missing.
    static func cursorLine(_ media: MediaSnapshot?) -> String {
        guard let media, takesCursor(media) else { return "Select a video in the list" }
        guard let cursor = media.cursor else { return "No cursor file" }
        let name = (cursor.path as NSString).lastPathComponent
        return cursorMissing(media) ? "\(name) — missing" : name
    }

    /// Locate…: an open panel of `.fjcursor` files, the import's attach check
    /// against this media, then one step — or an alert with the check's
    /// sentence and nothing edited.
    func locateCursor(_ media: MediaSnapshot) {
        guard let window = window else {
            NSSound.beep()
            return
        }
        let binding = self.binding
        let panel = NSOpenPanel()
        panel.allowsMultipleSelection = false
        panel.canChooseDirectories = false
        if let type = UTType(filenameExtension: CursorFileWriter.fileExtension) {
            panel.allowedContentTypes = [type]
        }
        panel.message = "Choose the cursor file for “\(media.name)”."
        panel.beginSheetModal(for: window) { response in
            guard response == .OK, let url = panel.url else { return }
            switch MediaImporter.cursorAttachment(at: url, to: MediaDescriptor(media)) {
            case .success(let attachment):
                binding.applyGrouped(
                    "Locate Cursor File",
                    [.setMediaCursor(media: media.id, cursor: attachment.cursor)])
            case .failure(let problem):
                // The panel's sheet is still ending; the alert waits a turn.
                DispatchQueue.main.async {
                    let alert = NSAlert()
                    alert.messageText = "The cursor file was not attached"
                    alert.informativeText = problem.message
                    alert.beginSheetModal(for: window)
                }
            }
        }
    }
}

