478:    pub fn add_media(&self, descriptor: &Value) -> Result<Outcome, String> {

    pub fn add_media(&self, descriptor: &Value) -> Result<Outcome, String> {
        let Value::Object(fields) = descriptor else {
            return Err(format!(
                "a media descriptor must be a json object, not {}",
                describe(descriptor)
            ));
        };
        if fields.contains_key("id") {
            return Err(format!(
                "a media descriptor must not carry an id: the project assigns it (this one gets {})",
                self.next_id
            ));
        }
        for key in fields.keys() {
            if !MEDIA_KEYS.contains(&key.as_str()) {
                return Err(format!("unknown key \"{key}\" in a media descriptor"));
            }
        }

        // Deserializing through `Media` itself means the descriptor's
        // schema is the model's schema — `kind` is checked against the
        // three variants, `fps` against `[num, den]` — with no second
        // spelling of it here. The id is stamped in first because `Media`
        // requires one.
        let mut with_id = descriptor.clone();
        if let Value::Object(map) = &mut with_id {
            map.insert("id".to_string(), Value::from(self.next_id));
        }
        let mut media: Media = serde_json::from_value(with_id)
            .map_err(|e| format!("media descriptor does not match the schema: {e}"))?;

        media.original = normalize_original(media.original);
        check_media_fields(&media)?;
        // A descriptor's `color` is the probe's detected Camera Log (spec §11
        // GR-16), held to the rules `set_media_color` holds a setting to.
        self.check_media_color(&media)?;
        let path = media.path.trim().to_string();
        if self.media.iter().any(|m| m.path == path) {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        let mut record = media;
        record.id = next.allocate_id();
        record.path = path;
        // An empty bookmark is not a bookmark; storing one would make
        // `relink` think the file had been located once.
        record.bookmark = record.bookmark.filter(|b| !b.trim().is_empty());
        binding.invalidate()
        let clips = selectedClips

        // Picking a clip in the timeline or on the canvas asks about THAT
        // clip, so the panel answers about it — one selection model, and the
        // panel is one of its three views (the timeline bar's block and the
        // canvas handles are the others).
        // Switched in place rather than through `select(_:)`: that one starts
        // a refresh of its own, and this one is already running — with
        // `isLive` in hand, which a nested call would drop.
        let ids = clips.map { $0.id }
        // A different clip and a different tab are the two things that make
        // the panel a different list, so they are the two that send it back to
        // the top; everything else leaves the user where they were reading.
        var toTop = false
        if ids != lastSelection {
            lastSelection = ids
            toTop = true
            (pane(for: .clip) as? ClipPane)?.forgetSubTab()
            if !clips.isEmpty, tab == .media || tab == .document {  // AI-14
                tab = .clip
                buildTabs()
            }
        }

        let pane = pane(for: tab)
        if showPane(pane) { toTop = true }
        let signature = pane.structureSignature
        // A rebuild replaces every control, so it must never happen under a
        // live gesture — the slider being dragged would vanish mid-drag.
        if signature != lastSignature, !isLive, document?.isLiveEditing != true {
            lastSignature = signature
            pane.rebuild()
            installPinned(pane.pinnedBlock)
        }
        pane.refresh()
        if toTop { scrollToTop() }
    }
}
